 /** True when a refused request is owned by its own page (shown there), so it must not raise the global error banner. */
 boolean scopedFailure(String path,int status){return false;}
 void request(String path,JSONObject payload,Done done){request(path,payload,null,done);}
 void request(String path,JSONObject payload,Runnable failed,Done done){requestStatus(path,payload,failed==null?null:status->failed.run(),done);}
 /** Same as request(), but a failure reports its HTTP status (0 = the backend could not be reached), so a page that owns its own error state can tell offline from refused. */
 void requestStatus(String path,JSONObject payload,Failure failure,Done done){final String base=Backend.base(getPreferences(0));final String authToken=token.equals(Backend.token(getPreferences(0)))?token:"";io.execute(()->{try{Request.Builder b=new Request.Builder().url(base+path);if(!authToken.isEmpty())b.header("Authorization","Bearer "+authToken);if(payload!=null)b.post(RequestBody.create(payload.toString(),MediaType.get("application/json")));try(Response r=http.newCall(b.build()).execute()){JSONObject result=new JSONObject(r.body().string());if(!r.isSuccessful()){String error=result.optString("error","Server unavailable");final int code=r.code();ui.post(()->{if(!scopedFailure(path,code))message(error);if(failure!=null)failure.onFailure(code);});return;}ui.post(()->{if(isFinishing())return;try{done.accept(result);}catch(Exception e){message("Could not display the server response.");}});}}catch(Exception e){ui.post(()->{message("Cannot reach the SG Sports backend. Check the TV's home network connection.");if(failure!=null)failure.onFailure(0);});}});}
