 void shell(String section){backTarget=this::drawHome;homeScreen=section.startsWith("Today");LinearLayout root=new LinearLayout(this);root.setBackgroundColor(BG);LinearLayout rail=vertical();rail.setGravity(Gravity.CENTER_HORIZONTAL);rail.setPadding(dp(7),dp(20),dp(7),dp(16));rail.setBackgroundColor(Color.rgb(10,10,12));root.addView(rail,new LinearLayout.LayoutParams(dp(70),-1));TextView brand=text("SG",25,FG);brand.setTypeface(null,Typeface.BOLD);rail.addView(brand);TextView small=text("SPORTS",9,MUTED);rail.addView(small);Space gap=new Space(this);rail.addView(gap,new LinearLayout.LayoutParams(1,dp(28)));String[] names={"⌂\nHome","▦\nSports","≡\nLeagues","⚙\nSettings"};Runnable[] actions={this::loadHome,()->loadSports(false),()->loadSports(true),this::settings};for(int i=0;i<names.length;i++){Button b=button(names[i],actions[i]);b.setTextSize(11);b.setPadding(0,dp(5),0,dp(5));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(56));bp.bottomMargin=dp(12);rail.addView(b,bp);}ScrollView scroll=new ScrollView(this);scroll.setFocusable(false);scroll.setVerticalScrollBarEnabled(false);scroll.setClipToPadding(false);scroll.setPadding(dp(30),dp(20),dp(30),dp(24));root.addView(scroll,new LinearLayout.LayoutParams(0,-1,1));content=vertical();scroll.addView(content);setContentView(root);LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);TextView title=text(section,21,FG);title.setTypeface(null,Typeface.BOLD);top.addView(title,new LinearLayout.LayoutParams(0,-2,1));TextClock clock=new TextClock(this);clock.setFormat12Hour("h:mm a");clock.setTextColor(FG);clock.setTextSize(17);top.addView(clock);content.addView(top);}
