 JSONObject assetMap(String file){try(java.io.InputStream in=getAssets().open(file)){java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();byte[] buffer=new byte[4096];int count;while((count=in.read(buffer))!=-1)bytes.write(buffer,0,count);return new JSONObject(bytes.toString("UTF-8"));}catch(Exception e){return new JSONObject();}}
