 View logo(String name,String file,int size){android.widget.FrameLayout box=new android.widget.FrameLayout(this);box.setContentDescription(name);TextView fallback=text(name.isEmpty()?"TV":name.substring(0,Math.min(2,name.length())).toUpperCase(Locale.ROOT),size>40?20:11,FG);fallback.setGravity(Gravity.CENTER);box.addView(fallback,new android.widget.FrameLayout.LayoutParams(-1,-1));if(!file.isEmpty())try(java.io.InputStream in=getAssets().open(file)){ImageView image=new ImageView(this);image.setImageDrawable(android.graphics.drawable.Drawable.createFromStream(in,null));image.setScaleType(ImageView.ScaleType.FIT_CENTER);box.removeAllViews();box.addView(image,new android.widget.FrameLayout.LayoutParams(-1,-1));}catch(Exception ignored){}box.setLayoutParams(new LinearLayout.LayoutParams(dp(size),dp(size)));return box;}

 JSONObject leagueMarks; JSONArray identities;
 android.graphics.drawable.Drawable brandDrawable(String label){if(leagueMarks==null)leagueMarks=assetMap("leagues.json");String file=leagueMarks.optString(label);if(!file.isEmpty())try(java.io.InputStream in=getAssets().open(file)){return android.graphics.drawable.Drawable.createFromStream(in,null);}catch(Exception ignored){}if(Arrays.asList(chosenSports).contains(label))return new SportMark(label);return null;}
 View leagueLogo(String league,int size){if(league.equals("Majors")){ImageView mark=new ImageView(this);mark.setImageDrawable(new SportMark("Golf"));mark.setLayoutParams(new LinearLayout.LayoutParams(dp(size),dp(size)));return mark;}if(leagueMarks==null)leagueMarks=assetMap("leagues.json");return logo(league,leagueMarks.optString(league),size);}
 class SportMark extends android.graphics.drawable.Drawable {final String sport;final android.graphics.Paint paint=new android.graphics.Paint(3);SportMark(String value){sport=value;}public void draw(android.graphics.Canvas canvas){canvas.save();canvas.translate(getBounds().left,getBounds().top);canvas.scale(getBounds().width()/100f,getBounds().height()/100f);paint.setStrokeWidth(5);paint.setStyle(android.graphics.Paint.Style.FILL);paint.setColor(sport.equals("Softball")?Color.rgb(237,219,62):FG);if(sport.equals("Football")){canvas.save();canvas.rotate(-30,50,50);canvas.drawOval(8,25,92,75,paint);paint.setColor(Color.BLACK);canvas.drawLine(30,50,70,50,paint);for(int x=35;x<=65;x+=10)canvas.drawLine(x,40,x,60,paint);canvas.restore();}else if(sport.equals("Golf")){paint.setStyle(android.graphics.Paint.Style.STROKE);canvas.drawLine(35,15,35,80,paint);paint.setStyle(android.graphics.Paint.Style.FILL);android.graphics.Path path=new android.graphics.Path();path.moveTo(37,15);path.lineTo(80,30);path.lineTo(37,45);path.close();canvas.drawPath(path,paint);canvas.drawOval(15,78,85,90,paint);}else if(sport.equals("UFC")){paint.setTextSize(30);paint.setTypeface(Typeface.DEFAULT_BOLD);paint.setTextAlign(android.graphics.Paint.Align.CENTER);canvas.drawText(sport,50,60,paint);}else{canvas.drawCircle(50,50,42,paint);paint.setColor(sport.equals("Soccer")?Color.BLACK:Color.rgb(182,43,42));if(sport.equals("Soccer")){android.graphics.Path path=new android.graphics.Path();for(int i=0;i<5;i++){double a=Math.PI*2*i/5-Math.PI/2;float x=50+(float)Math.cos(a)*20,y=50+(float)Math.sin(a)*20;if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}path.close();canvas.drawPath(path,paint);paint.setStyle(android.graphics.Paint.Style.STROKE);canvas.drawCircle(50,50,34,paint);}else{paint.setStyle(android.graphics.Paint.Style.STROKE);canvas.drawArc(0,10,45,90,-65,130,false,paint);canvas.drawArc(55,10,100,90,115,130,false,paint);}}canvas.restore();}public void setAlpha(int alpha){paint.setAlpha(alpha);}public void setColorFilter(android.graphics.ColorFilter filter){paint.setColorFilter(filter);}public int getOpacity(){return android.graphics.PixelFormat.TRANSLUCENT;}}
 LinearLayout eventArtwork(JSONObject event){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.addView(leagueLogo(event.optString("league"),24));if(identities==null)try(java.io.InputStream in=getAssets().open("team-identities.json")){java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)bytes.write(b,0,n);identities=new JSONArray(bytes.toString("UTF-8"));}catch(Exception ex){identities=new JSONArray();}String title=event.optString("title").toLowerCase(Locale.ROOT);int found=0;for(int i=0;i<identities.length()&&found<2;i++){JSONObject t=identities.optJSONObject(i);String league=t.optString("league");if(!league.equals(event.optString("league"))&&!(event.optString("sport").equals("Soccer")&&t.optString("sport").equals("soccer")))continue;JSONArray aliases=t.optJSONArray("aliases");boolean match=false;for(int j=0;aliases!=null&&j<aliases.length();j++){String alias=aliases.optString(j).toLowerCase(Locale.ROOT);String pattern="(?<![a-z])"+java.util.regex.Pattern.quote(alias)+"(?![a-z])";if(league.equals("NCAA"))pattern+="(?! (?:state|tech|southern|atlantic|international|el[ -]paso|san antonio|a&m))";if(league.equals("NCAA")&&(alias.equals("florida")||alias.equals("texas")||alias.equals("alabama")))pattern+="(?! a&m)";if(java.util.regex.Pattern.compile(pattern).matcher(title).find()){match=true;break;}}if(match){View image=logo(t.optString("name"),t.optString("file"),28);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(28),dp(28));lp.leftMargin=dp(8);row.addView(image,lp);found++;}}return row;}
 View teamLogo(String name,int size){if(teamLogos==null)teamLogos=assetMap("teams.json");return logo(name,teamLogos.optString(name),size);}
 View channelLogo(JSONObject feed,int size){if(channelLogos==null)channelLogos=assetMap("channels.json");return logo("TV",channelLogos.optString(feed.optString("provider_id")+"_"+feed.optString("stream_id")),size);}
 String team(JSONObject f,boolean left){return f.optBoolean("home",true)==left?"FC Barcelona":f.optString("opponent");}
 LinearLayout teamLine(String name,int size){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.addView(teamLogo(name,size));TextView label=text(name.equals("FC Barcelona")?"Barcelona":name,size>40?25:18,FG);label.setTypeface(null,Typeface.BOLD);label.setMaxLines(1);label.setEllipsize(android.text.TextUtils.TruncateAt.END);label.setPadding(dp(10),0,0,0);row.addView(label,new LinearLayout.LayoutParams(0,-2,1));return row;}
 LinearLayout gameHero(JSONObject f,JSONArray feeds,boolean clickable){LinearLayout hero=vertical();hero.setPadding(dp(18),dp(12),dp(18),dp(12));hero.setBackground(surface(Color.rgb(34,24,43),Color.rgb(13,29,49),Color.rgb(40,40,43)));hero.addView(text(f.optString("competition").toUpperCase(Locale.ROOT),12,MUTED));LinearLayout match=new LinearLayout(this);match.setGravity(Gravity.CENTER_VERTICAL);match.addView(teamLine(team(f,true),54),new LinearLayout.LayoutParams(0,dp(78),1));TextView vs=text("vs",25,FG);vs.setGravity(Gravity.CENTER);match.addView(vs,new LinearLayout.LayoutParams(dp(68),-2));match.addView(teamLine(team(f,false),54),new LinearLayout.LayoutParams(0,dp(78),1));hero.addView(match);LinearLayout foot=new LinearLayout(this);foot.setGravity(Gravity.CENTER_VERTICAL);foot.addView(text(date(f.optLong("kickoff")),14,FG),new LinearLayout.LayoutParams(0,-2,1));if(feeds!=null)for(int i=0;i<Math.min(4,feeds.length());i++)foot.addView(channelLogo(feeds.optJSONObject(i),28));TextView more=text(clickable?"   SEE CHANNELS  ›":"",12,FG);foot.addView(more);hero.addView(foot);if(clickable){focus(hero);hero.setOnClickListener(v->showFeeds(f));}return hero;}
 void drawHome(){shell("Today  ·  "+new SimpleDateFormat("EEEE, MMM d",Locale.getDefault()).format(new Date()));JSONObject game=home.optJSONObject("game");JSONObject f=game==null?null:game.optJSONObject("fixture");heading("NEXT UP");if(f==null){content.addView(text("No upcoming games in the schedule.",18,MUTED));drawFavorites(null);return;}LinearLayout hero=gameHero(f,game.optJSONArray("feeds"),true);content.addView(hero,new LinearLayout.LayoutParams(-1,dp(150)));hero.post(()->hero.requestFocus());heading("UPCOMING GAMES");HorizontalScrollView strip=new HorizontalScrollView(this);strip.setFocusable(false);strip.setHorizontalScrollBarEnabled(false);strip.setClipToPadding(false);strip.setPadding(dp(3),dp(3),dp(3),dp(3));LinearLayout row=new LinearLayout(this);strip.addView(row);JSONArray fixtures=home.optJSONArray("fixtures");if(fixtures!=null)for(int i=0;i<Math.min(12,fixtures.length());i++){JSONObject item=fixtures.optJSONObject(i);LinearLayout card=vertical();card.setPadding(dp(12),dp(10),dp(12),dp(10));card.setBackground(surface(PANEL,Color.rgb(12,13,17),Color.rgb(40,40,43)));focus(card);card.addView(text(new SimpleDateFormat("EEE, MMM d · h:mm a",Locale.getDefault()).format(new Date(item.optLong("kickoff")*1000)),11,MUTED));card.addView(teamLine(team(item,true),27),new LinearLayout.LayoutParams(-1,dp(39)));card.addView(teamLine(team(item,false),27),new LinearLayout.LayoutParams(-1,dp(39)));TextView competition=text(item.optString("competition"),11,MUTED);competition.setSingleLine(true);competition.setEllipsize(android.text.TextUtils.TruncateAt.END);competition.setPadding(0,dp(8),0,0);card.addView(competition);card.setOnClickListener(v->showFeeds(item));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(dp(210),dp(142));cp.rightMargin=dp(12);row.addView(card,cp);}content.addView(strip);drawFavorites(f);}

 void drawFavorites(JSONObject barcelona){heading("MY TEAMS");LinearLayout row=horizontalRail();JSONArray teams=assetMap("favorites.json").optJSONArray("teams");if(teams==null)return;for(int i=0;i<teams.length();i++){JSONObject team=teams.optJSONObject(i);LinearLayout tile=vertical();tile.setPadding(dp(12),dp(10),dp(12),dp(10));tile.setBackground(surface(PANEL,PANEL,Color.rgb(40,40,43)));focus(tile);tile.addView(logo(team.optString("name"),team.optString("logo"),36));TextView name=text(team.optString("name"),16,FG);name.setTypeface(null,Typeface.BOLD);name.setMaxLines(2);tile.addView(name,new LinearLayout.LayoutParams(-1,dp(44)));tile.addView(text(team.optString("sport"),12,MUTED));tile.setOnClickListener(v->{if(team.optBoolean("barcelona")){if(barcelona!=null)showFeeds(barcelona);else message("No upcoming Barcelona kickoff is listed yet.");}else showFavorite(team);});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(190),dp(123));lp.rightMargin=dp(12);row.addView(tile,lp);}}
 void showFavorite(JSONObject team){if(token.isEmpty()){pairDialog();return;}shell(team.optString("name"));content.addView(text("Loading your team's guide listings…",16,MUTED));request("/tv/sports",null,data->{shell(team.optString("name"));content.addView(logo(team.optString("name"),team.optString("logo"),54));heading(team.optString("sport").toUpperCase(Locale.ROOT)+" · ON NOW");JSONArray events=data.optJSONArray("events");java.util.regex.Pattern match=java.util.regex.Pattern.compile(team.optString("pattern"),java.util.regex.Pattern.CASE_INSENSITIVE);int count=0;if(events!=null)for(int i=0;i<events.length();i++){JSONObject e=events.optJSONObject(i);if(!team.optString("sport").equals(e.optString("sport"))||!team.optString("league").equals(e.optString("league"))||!match.matcher(e.optString("title")).find())continue;Button b=button(e.optString("title")+"\n"+date(e.optLong("start")),()->showSportsFeeds(e,()->showFavorite(team)));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(80));lp.bottomMargin=dp(10);content.addView(b,lp);if(count++==0)b.post(()->b.requestFocus());}if(count==0)content.addView(text(data.optBoolean("fresh")?"No matching program airing now in the current guide.":"The guide is updating. Try again shortly.",18,MUTED));});}
 void showFeeds(JSONObject fixture){if(token.isEmpty()){pairDialog();return;}request("/tv/feeds",obj("fixture_id",fixture.optString("id")),data->{shell("Game day");JSONArray feeds=data.optJSONArray("feeds");LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(-1,dp(150));hp.topMargin=dp(15);content.addView(gameHero(fixture,feeds,false),hp);heading("WHERE TO WATCH");if(feeds==null||feeds.length()==0){content.addView(text("No matching feeds listed yet.",18,MUTED));content.addView(button("Back to games",this::drawHome));return;}for(int i=0;i<feeds.length();i++){JSONObject feed=feeds.getJSONObject(i);LinearLayout row=new LinearLayout(this);row.setPadding(dp(14),dp(8),dp(14),dp(8));row.setGravity(Gravity.CENTER_VERTICAL);row.setBackground(surface(PANEL,Color.rgb(12,13,17),Color.rgb(40,40,43)));focus(row);row.addView(channelLogo(feed,46));LinearLayout labels=vertical();labels.setPadding(dp(14),0,dp(12),0);TextView name=text(feed.optString("display_name").replaceAll("#[0-9]+$","").replace("✪","").trim(),18,FG);name.setTypeface(null,Typeface.BOLD);name.setSingleLine(true);name.setEllipsize(android.text.TextUtils.TruncateAt.END);labels.addView(name);JSONObject audio=feed.optJSONObject("audio_language");String language=audio==null?"Audio unknown":audio.optString("name","Unknown");if(!language.equals("Unknown"))language+=" · listed audio";else language="Audio unknown";labels.addView(text(feed.optString("provider_id").toUpperCase(Locale.ROOT)+"  ·  "+language,12,MUTED));if(feed.optBoolean("requires_date_verification"))labels.addView(text("Schedule date needs verification",11,MUTED));row.addView(labels,new LinearLayout.LayoutParams(0,-2,1));row.addView(text("PLAY  ›",12,FG));final int feedIndex=i;row.setOnClickListener(v->startFeed(fixture,feeds,feedIndex));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,dp(76));rp.bottomMargin=dp(8);content.addView(row,rp);if(i==0)row.post(()->row.requestFocus());}});}

 void loadSports(boolean leagues){if(token.isEmpty()){pairDialog();return;}shell(leagues?"Leagues":"Sports");content.addView(text("Loading the program guide…",18,MUTED));request("/tv/sports",null,data->{sportsData=data;if(leagues)drawLeagues();else drawSports("","");});}
 int airingCount(String sport,String league){int count=0;JSONArray events=sportsData.optJSONArray("events");if(events!=null)for(int i=0;i<events.length();i++){JSONObject e=events.optJSONObject(i);if((sport.isEmpty()||sport.equals(e.optString("sport")))&&(league.isEmpty()||league.equals(e.optString("league"))))count++;}return count;}
 LinearLayout horizontalRail(){HorizontalScrollView strip=new HorizontalScrollView(this);strip.setFocusable(false);strip.setHorizontalScrollBarEnabled(false);strip.setPadding(dp(3),dp(5),dp(3),dp(7));LinearLayout row=new LinearLayout(this);strip.addView(row);content.addView(strip);return row;}
 void chip(LinearLayout row,String label,boolean selected,Runnable action){Button b=button(label,action);android.graphics.drawable.Drawable mark=brandDrawable(label.replace("★ ",""));if(mark!=null){mark.setBounds(0,0,dp(23),dp(23));b.setCompoundDrawables(mark,null,null,null);b.setCompoundDrawablePadding(dp(8));}if(selected)b.setBackground(surface(Color.rgb(64,60,48),Color.rgb(35,33,27),ACCENT));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,dp(42));lp.rightMargin=dp(8);row.addView(b,lp);}
 String[] chosenSports={"Football","Soccer","Baseball","Softball","UFC","Golf"};
 void drawLeagues(){shell("Leagues");content.addView(text("Your competitions · programs airing now",14,MUTED));JSONObject sports=sportsData.optJSONObject("sports");if(sports==null)return;boolean first=true;for(String sport:chosenSports){heading(sport.toUpperCase(Locale.ROOT));LinearLayout row=horizontalRail();JSONArray leagues=sports.optJSONArray(sport);if(leagues==null)continue;for(int i=0;i<leagues.length();i++){String league=leagues.optString(i);LinearLayout tile=vertical();tile.setPadding(dp(14),dp(12),dp(14),dp(12));tile.setBackground(surface(PANEL,PANEL,Color.rgb(40,40,43)));focus(tile);tile.addView(leagueLogo(league,32));TextView name=text(league,18,FG);name.setTypeface(null,Typeface.BOLD);name.setMaxLines(2);tile.addView(name,new LinearLayout.LayoutParams(-1,dp(42)));tile.addView(text((league.equals("NCAA")?"★ SEC first · ":"")+airingCount(sport,league)+" on now",12,MUTED));tile.setOnClickListener(v->drawSports(sport,league));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(190),dp(130));lp.rightMargin=dp(12);row.addView(tile,lp);if(first){tile.post(()->tile.requestFocus());first=false;}}}}
 void drawSports(String sport,String league){if(!sport.equals(sportFilter)||!league.equals(leagueFilter))conferenceFilter="";sportFilter=sport;leagueFilter=league;shell(league.isEmpty()?"Sports · On now":league);content.addView(text("Program-guide listings · includes replays and studio shows",13,MUTED));LinearLayout filters=horizontalRail();chip(filters,"All",sport.isEmpty(),()->drawSports("",""));for(String name:chosenSports)chip(filters,name,name.equals(sport),()->drawSports(name,""));if(!sport.isEmpty()){JSONObject catalog=sportsData.optJSONObject("sports");JSONArray leagues=catalog==null?null:catalog.optJSONArray(sport);if(leagues!=null){LinearLayout lr=horizontalRail();chip(lr,"All competitions",league.isEmpty(),()->drawSports(sport,""));for(int i=0;i<leagues.length();i++){String name=leagues.optString(i);chip(lr,name,name.equals(league),()->drawSports(sport,name));}}}if(league.equals("NCAA")){LinearLayout cr=horizontalRail();chip(cr,"★ SEC",conferenceFilter.equals("SEC"),()->{conferenceFilter="SEC";drawSports(sport,league);});chip(cr,"All conferences",conferenceFilter.isEmpty(),()->{conferenceFilter="";drawSports(sport,league);});}heading("ON NOW"+(conferenceFilter.equals("SEC")?" · SEC":" · "+airingCount(sport,league)));if(!sportsData.optBoolean("fresh")){content.addView(text("The guide is updating. Current listings will appear after a successful refresh.",18,MUTED));content.addView(button("Refresh",()->loadSports(false)));return;}JSONArray events=sportsData.optJSONArray("events");int count=0;LinearLayout row=null;if(events!=null)for(int i=0;i<events.length();i++){JSONObject e=events.optJSONObject(i);if((!sport.isEmpty()&&!sport.equals(e.optString("sport")))||(!league.isEmpty()&&!league.equals(e.optString("league")))||(!conferenceFilter.isEmpty()&&!conferenceFilter.equals(e.optString("conference"))))continue;if(count%3==0){row=new LinearLayout(this);row.setPadding(dp(3),dp(3),dp(3),dp(9));content.addView(row);}LinearLayout card=vertical();card.setPadding(dp(12),dp(10),dp(12),dp(10));card.setBackground(surface(PANEL,Color.rgb(12,13,17),Color.rgb(40,40,43)));focus(card);card.addView(eventArtwork(e),new LinearLayout.LayoutParams(-1,dp(30)));card.addView(text(e.optBoolean("repeat")?"ON NOW · REPLAY":e.optBoolean("live_tag")?"LIVE · GUIDE":"ON NOW",11,ACCENT));TextView title=text(e.optString("title"),18,FG);title.setTypeface(null,Typeface.BOLD);title.setMaxLines(3);title.setEllipsize(android.text.TextUtils.TruncateAt.END);card.addView(title,new LinearLayout.LayoutParams(-1,dp(74)));card.addView(text((e.optString("conference").equals("SEC")?"★ SEC  ·  ":"")+e.optString("league"),11,e.optString("conference").equals("SEC")?Color.rgb(240,201,92):MUTED));card.addView(text(new SimpleDateFormat("h:mm a",Locale.getDefault()).format(new Date(e.optLong("start")*1000))+" – "+new SimpleDateFormat("h:mm a",Locale.getDefault()).format(new Date(e.optLong("end")*1000)),11,MUTED));JSONArray feeds=e.optJSONArray("feeds");card.addView(text((feeds==null?0:feeds.length())+" channels  ›",12,FG));card.setOnClickListener(v->showSportsFeeds(e));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,dp(194),1);cp.rightMargin=dp(10);row.addView(card,cp);if(count==0)card.post(()->card.requestFocus());count++;}if(row!=null)while(row.getChildCount()<3)row.addView(new Space(this),new LinearLayout.LayoutParams(0,1,1));if(count==0)content.addView(text("Nothing listed on now for this selection. Guide coverage can vary by league.",18,MUTED));}
 void showSportsFeeds(JSONObject event){showSportsFeeds(event,null);}
 void showSportsFeeds(JSONObject event,Runnable returnTo){request("/tv/sports/feeds",obj("event_id",event.optString("id")),data->{shell("Where to watch");backTarget=returnTo!=null?returnTo:()->drawSports(sportFilter,leagueFilter);content.addView(eventArtwork(data));heading(data.optString("title"));content.addView(text(data.optString("league")+" · "+date(data.optLong("start")),14,MUTED));JSONArray feeds=data.getJSONArray("feeds");for(int i=0;i<feeds.length();i++){JSONObject feed=feeds.getJSONObject(i);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(14),dp(8),dp(14),dp(8));row.setBackground(surface(PANEL,PANEL,Color.rgb(40,40,43)));focus(row);row.addView(channelLogo(feed,38));LinearLayout labels=vertical();labels.setPadding(dp(14),0,0,0);TextView name=text(feed.optString("display_name"),18,FG);name.setSingleLine(true);name.setEllipsize(android.text.TextUtils.TruncateAt.END);labels.addView(name);labels.addView(text(feed.optString("provider_id").toUpperCase(Locale.ROOT),12,MUTED));row.addView(labels,new LinearLayout.LayoutParams(0,-2,1));row.addView(text("PLAY  ›",12,FG));final int feedIndex=i;row.setOnClickListener(v->startFeed(obj("id",data.optString("id"),"event_id",data.optString("id")),feeds,feedIndex));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,dp(72));rp.topMargin=dp(10);content.addView(row,rp);if(i==0)row.post(()->row.requestFocus());}});}
 void startFeed(JSONObject f,JSONArray feeds,int index){JSONObject feed=feeds.optJSONObject(index);if(feed==null)return;playbackTitle=feed.optString("display_name","SG Sports");final int attempt=++generation;request("/tv/play",obj("fixture_id",f.optString("id"),"event_id",f.optString("event_id"),"provider_id",feed.optString("provider_id"),"stream_id",feed.optString("stream_id")),r->{String sid=r.getString("session");if(stopped||attempt!=generation){request("/tv/stop",obj("session",sid),x->{});return;}session=sid;activeFixture=f.optString("id");Intent playIntent=new Intent(this,PlayerActivity.class);playIntent.putExtra("session",sid);playIntent.putExtra("stream_path",r.getString("stream_path"));playIntent.putExtra("title",playbackTitle);playIntent.putExtra("fixture_id",f.optString("id"));playIntent.putExtra("event_id",f.optString("event_id"));playIntent.putExtra("feeds",feeds.toString());playIntent.putExtra("feed_index",index);if(playerExtras!=null)playIntent.putExtras(playerExtras);playerLauncher.launch(playIntent);});}
 void returnToBrowsing(){drawHome();}
 void settings(){new AlertDialog.Builder(this).setTitle("SG Sports settings").setItems(new String[]{"Pair this TV", "Preferred audio: "+new Locale(selectedLanguage).getDisplayLanguage(),"Refresh games","Forget pairing"},(d,index)->{if(index==0)pairDialog();if(index==1)new AlertDialog.Builder(this).setTitle("Preferred audio").setItems(new String[]{"English","Spanish","Portuguese","French","Arabic"},(dd,ii)->{selectedLanguage=new String[]{"en","es","pt","fr","ar"}[ii];getPreferences(0).edit().putString("language",selectedLanguage).apply();}).show();if(index==2)loadHome();if(index==3){request("/tv/unpair",obj(),r->{token="";Backend.forgetPairing(getPreferences(0));message("Pairing removed from this backend.");});}}).show();}
 void pairDialog(){EditText input=new EditText(this);input.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);input.setHint("6-digit code");new AlertDialog.Builder(this).setTitle("Pair SG Sports").setMessage("Open "+Backend.base(getPreferences(0))+" on your phone or Mac and choose Pair TV. Enter the code here.").setView(input).setPositiveButton("Pair",(d,w)->request("/tv/pair",obj("code",input.getText().toString().trim()),r->{token=r.getString("token");Backend.savePairing(getPreferences(0),token);message("TV paired. Choose a game to see its feeds.");})).setNegativeButton("Cancel",null).show();}
 @Override protected void onStart(){super.onStart();if(stopped&&home!=null)loadHome();stopped=false;}
 @Override protected void onStop(){stopped=true;super.onStop();}
 @Override public void onBackPressed(){if(home!=null&&!homeScreen){if(backTarget!=null)backTarget.run();else drawHome();}else super.onBackPressed();}
 @Override protected void onDestroy(){io.shutdown();super.onDestroy();}
